import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;
import org.apache.abdera.parser.ParserException;

/**
 * Secure implementation of an Atom provider.
 *
 * The original implementation reused a shared {@link Parser} instance and
 * configured the {@link ParserOptions} inside a synchronized block.  This
 * approach could allow another thread to invoke {@code parse()} before the
 * options were applied, re‑enabling entity resolution and exposing the
 * application to XML External Entity (XXE) attacks.
 *
 * The patched version creates a fresh {@link Parser} for each request and
 * configures a dedicated {@link ParserOptions} instance **before** parsing.
 * This guarantees that entity resolution is disabled for every parsing
 * operation, eliminates the need for synchronization, and removes the
 * shared mutable state that caused the race condition.
 *
 * @param <T> the type of Atom element handled by the provider
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  MessageBodyReader implementation (patched)
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Create a brand‑new parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Configure parser options *before* any parsing occurs.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Critical: disable entity resolution to prevent XXE.
        options.setResolveEntities(false);
        // Defensive: also disable DTD processing if the underlying parser supports it.
        // (If the method does not exist, this line is a no‑op at compile time.)
