                   .getMethod("setSupportDTD", boolean.class)
                   .invoke(options, false);
        } catch (ReflectiveOperationException ignored) {
            // Method not available in this version of Abdera – ignore.
        }

        // Parse the input using the securely configured options.
        Document<T> doc;
        try {
            doc = parser.parse(entityStream, options);
        } catch (ParserException e) {
            // Translate parser‑specific exceptions to IOException as required by the JAX‑RS contract.
            throw new IOException("Failed to parse Atom XML payload", e);
        }

        // The document is guaranteed to be non‑null; return its root element.
        return doc.getRoot();
