public static File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("dir is null");
    if (name == null) throw new IllegalArgumentException("name is null");
    // strip query part
    int q = name.indexOf('?');
    if (q > 0) name = name.substring(0, q);
    // Normalize name: replace backslashes with forward slash, remove leading slash
    name = name.replace('\\', '/');
    // Remove any leading '/' to avoid absolute path
    while (name.startsWith("/")) name = name.substring(1);
    // Reject path traversal components
    if (name.contains("..") || name.contains("/") || name.contains("\\")) {
        // If contains '/', we already replaced with '/', but we still reject subdirectories.
        // Instead we could extract only the file name part after last slash.
        // Safer: take only the last segment.
        int lastSlash = Math.max(name.lastIndexOf('/'), name.lastIndexOf('\\'));
        if (lastSlash >= 0) {
            name = name.substring(lastSlash + 1);
        }
    }
    // After sanitization, ensure name is not empty
    if (name.isEmpty()) {
        throw new IllegalArgumentException("Invalid file name after sanitization");
    }

    File file = new File(dir, name);
    // Ensure file is within dir
    try {
        String canonicalDir = dir.getCanonicalPath();
        String canonicalFile = file.getCanonicalPath();
        if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
            throw new IllegalArgumentException("Attempted directory traversal attack: " + name);
        }
    } catch (IOException e) {
        throw new IllegalStateException("Failed to resolve canonical paths", e);
    }

    // Determine prefix/suffix for duplicate handling using sanitized name
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
        // re-check canonical path each iteration (should stay within dir)
        try {
            if (!file.getCanonicalPath().startsWith(dir.getCanonicalPath() + File.separator)) {
                throw new IllegalArgumentException("Generated file escapes target directory");
            }
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}

