protected void extractFile(final File srcF,
                           final File dir,
                           final InputStream compressedInputStream,
                           final String entryName,
                           final Date entryDate,
                           final boolean isDirectory,
                           final Integer mode,
                           String symlinkDestination) throws IOException, ArchiverException {
    if (entryName == null) {
        throw new ArchiverException("Entry name is null");
    }

    // Resolve the target file relative to the destination directory
    final File target = FileUtils.resolveFile(dir, entryName);

    // Validate that the resolved path does not escape the destination directory (Zip‑Slip protection)
    final Path canonicalDir = dir.getCanonicalFile().toPath();
    final Path canonicalTarget = target.getCanonicalFile().toPath();

    if (!canonicalTarget.startsWith(canonicalDir)) {
        throw new ArchiverException(
                "Entry is outside of the target directory (entryName=" + entryName + ")");
    }

    // Prevent a regular entry from overwriting an existing symbolic link
    if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTarget)) {
        throw new ArchiverException(
                "Refusing to overwrite existing symbolic link (entryName=" + entryName + ")");
    }

    try {
        // Overwrite check
        if (!isOverwrite() && target.exists() && (target.lastModified() >= entryDate.getTime())) {
            return;
        }

        // Ensure parent directories exist
        final File parent = target.getParentFile();
        if (parent != null) {
            parent.mkdirs();
        }

        if (!StringUtils.isEmpty(symlinkDestination)) {
            // Create a symbolic link
            SymlinkUtils.createSymbolicLink(target, new File(symlinkDestination));
        } else if (isDirectory) {
            // Create a directory entry
            target.mkdirs();
        } else {
            // Write regular file content
            try (OutputStream out = new FileOutputStream(target)) {
                IOUtil.copy(compressedInputStream, out);
            }
        }

        // Preserve timestamp
        target.setLastModified(entryDate.getTime());

        // Preserve permissions when required
        if (!isIgnorePermissions() && mode != null && !isDirectory) {
            ArchiveEntryUtils.chmod(target, mode);
        }
    } catch (final FileNotFoundException ex) {
        getLogger().warn("Unable to expand to file " + target.getPath());
    }
}
