/**
 * Normalises a URI path component.
 *
 * <p>The original implementation only stripped excess leading slashes but failed to
 * guarantee that a single leading slash is present.  When a path without a leading
 * slash (e.g. {@code "foo/bar"}) is later combined with a {@link java.net.URI},
 * the string can be interpreted as a scheme‑specific part (host, etc.) leading to
 * malformed URIs and potential security issues such as URL spoofing.</p>
 *
 * <p>This method now enforces the following rules:</p>
 * <ul>
 *   <li>If {@code path} is {@code null}, {@code null} is returned.</li>
 *   <li>If {@code path} is empty or consists solely of slashes, a single {@code "/"} is returned.</li>
 *   <li>All leading slashes are collapsed to exactly one leading slash.</li>
 *   <li>Any trailing characters (including additional slashes, query strings,
 *       fragments, etc.) are left untouched.</li>
 * </ul>
 *
 * @param path the raw path component, may be {@code null}
 * @return a normalised path that always starts with a single '/', or {@code null}
 *         if the input was {@code null}
 */
private static String normalizePath(final String path) {
    if (path == null) {
        return null;
    }

    // Fast path for the most common correct input.
    if (path.startsWith("/") && !path.startsWith("//")) {
        return path;
    }

    int leadingSlashCount = 0;
    final int length = path.length();

    // Count consecutive leading '/' characters.
    while (leadingSlashCount < length && path.charAt(leadingSlashCount) == '/') {
        leadingSlashCount++;
    }

    // If the whole string is made of slashes, return a single "/".
    if (leadingSlashCount == length) {
        return "/";
    }

    // Extract the remainder of the path after the leading slashes.
    String remainder = path.substring(leadingSlashCount);

    // Ensure exactly one leading slash.
    return "/" + remainder;
}
