 * of locale patterns and ensures that the resulting {@link Locale} is one of the
 * JVM‑supported locales before it is used.
 * </p>
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Pattern that matches valid locale strings such as "en", "en_US" or "en_US_POSIX". */
    private static final Pattern LOCALE_PATTERN = Pattern.compile(
            "^[a-zA-Z]{2,3}" +               // language (2‑3 letters)
            "(?:_[a-zA-Z]{2})?" +           // optional country (2 letters)
            "(?:_[a-zA-Z0-9]+)?$"            // optional variant
    );

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}.  The input is validated
     * against a whitelist of acceptable locale formats and against the set of
     * locales supported by the JVM.  Invalid or potentially malicious inputs are
     * rejected and logged.
     *
     * @param requestedLocale the parameter from the request
     * @return a validated {@link Locale} or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // If the caller already supplied a Locale instance, trust it (it cannot be XSS‑payload).
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already Locale): {}", locale);
            return locale;
        }

        // Convert to String, trim whitespace and reject empty values.
        String localeStr = requestedLocale.toString().trim();
        if (localeStr.isEmpty()) {
            LOG.warn("Requested locale string is empty after trimming; ignoring.");
            return null;
        }

        // Validate the format against the whitelist pattern.
        Matcher matcher = LOCALE_PATTERN.matcher(localeStr);
        if (!matcher.matches()) {
            LOG.warn("Requested locale '{}' does not match the allowed pattern; ignoring.", localeStr);
            return null;
        }

        // Parse the string into a Locale object.
        Locale locale = LocalizedTextUtil.localeFromString(localeStr, null);
        if (locale == null) {
            LOG.warn("Locale parsing failed for '{}'; ignoring.", localeStr);
            return null;
        }

        // Ensure the locale is one of the JVM‑supported locales.
        if (!isSupportedLocale(locale)) {
            LOG.warn("Locale '{}' is not among the JVM supported locales; ignoring.", locale);
            return null;
        }

        LOG.debug("Applied request locale: {}", locale);
        return locale;
    }

    /**
