import java.util.regex.Pattern;

public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);
    protected Pattern allowedActionNames = Pattern.compile("[a-zA-Z0-9._!/\\-]*");

    // other methods

    /**
     * Validates the action name against a whitelist pattern.
     * <p>
     * If the name matches the {@code allowedActionNames} pattern it is returned unchanged.
     * Otherwise the method rejects the input and returns an empty string.  This
     * prevents any attempt to “clean” a malicious name by stripping characters,
     * which could leave dangerous payloads intact.
     * </p>
