     * @param rawActionName action name extracted from URI; may be {@code null}
     * @return the original name if it is valid; otherwise an empty string
     */
    protected String cleanupActionName(final String rawActionName) {
        // Defensive null‑check – a null name cannot be processed safely.
        if (rawActionName == null) {
            LOG.warn("Received a null action name; returning empty string.");
            return "";
        }

        // If the name conforms to the whitelist pattern, accept it.
        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        }

        // Name is invalid – log the incident and reject the value.
        if (LOG.isWarnEnabled()) {
            LOG.warn(
                "Action/method [#0] does not match allowed action names pattern [#1]; rejecting it.",
                rawActionName,
                allowedActionNames.pattern()
            );
        }

        // Reject the malformed name by returning a safe, neutral value.
        return "";
    }

