import javax.xml.stream.XMLStreamReader;
import com.google.refine.importers.tree.TreeImportingParserBase;

public class XmlImporter extends TreeImportingParserBase {

    // other methods

    /**
     * Creates a securely configured {@link XMLStreamReader} from the supplied {@link InputStream}.
     * <p>
     * The factory is hardened against XML External Entity (XXE) attacks by:
     * <ul>
     *   <li>Disabling DTD processing ({@link XMLInputFactory#SUPPORT_DTD}).</li>
     *   <li>Disabling support for external entities ({@link XMLInputFactory#IS_SUPPORTING_EXTERNAL_ENTITIES}).</li>
     *   <li>Ensuring namespace awareness (optional but recommended).</li>
     * </ul>
     * Existing parser behaviour (coalescing and entity replacement) is retained.
     *
     * @param inputStream the raw XML input stream
     * @return a configured {@link XMLStreamReader}
     * @throws XMLStreamException if the underlying parser cannot be created
     * @throws IOException        if an I/O error occurs while wrapping the stream
     */
    private static final XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        XMLInputFactory factory = XMLInputFactory.newInstance();

        // --------------------------------------------------------------------
        // Harden the factory against XXE attacks.
        // --------------------------------------------------------------------
        // Disable DTDs entirely – most XML payloads processed by Refine do not
        // require them and disabling removes the attack surface.
        try {
            factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
        } catch (IllegalArgumentException ignored) {
            // Some implementations (e.g., older Woodstox versions) may not expose this
            // property. In that case we rely on disabling external entities below.
        }

        // Prevent the parser from resolving external entities.
        try {
            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
        } catch (IllegalArgumentException ignored) {
            // If the property is not supported we continue; the parser will still
            // behave safely for most modern factories.
        }

        // Ensure namespace handling is explicitly enabled – this does not affect
        // security but guarantees consistent parsing behaviour.
        try {
            factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, Boolean.TRUE);
        } catch (IllegalArgumentException ignored) {
            // No‑op if the implementation does not support the property.
        }

        // --------------------------------------------------------------------
        // Preserve the original functional settings.
        // --------------------------------------------------------------------
        factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);

        // Wrap the original stream to strip any unwanted XML prefixes (existing behaviour).
        InputStream safeStream = wrapPrefixRemovingInputStream(inputStream);

        // Create the XMLStreamReader with the hardened factory.
        return factory.createXMLStreamReader(safeStream);
    }

